export function compatibleBlockTypography(percent: number) {
  const scope = '[data-monitor-font-scale="' + percent + '"]', factor = percent / 100;
  return scope + '{font-size:' + 13 * factor + 'px}' + rules.map(rule => {
    let css = rule.selectors.map(selector => scope + ' ' + selector).join(',') + '{font-size:' + Number((rule.size * factor).toFixed(4)) + 'px}';
    for (const media of [...rule.media].reverse()) css = '@media ' + media + '{' + css + '}';
    return css;
  }).join('');
}
